  border-color: rgba(201,162,39,0.55);
}
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_btn {
  background: linear-gradient(to bottom, #334155 0%, #1e293b 100%);
  color: #cbd5e1;
  border-color: #475569;
}
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_btn:hover:not(:disabled) {
  background: linear-gradient(to bottom, #475569 0%, #334155 100%);
  color: #f2d866;
  border-color: #64748b;
}
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_btn_remove:hover {
  background: #7f1d1d !important;
  color: #fecaca !important;
  border-color: #b91c1c !important;
}
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_locked { color: #f2d866; }
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_empty { color: #64748b; }
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_resetrow {
  border-top-color: #334155;
}
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_reset { color: #64748b; }
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_reset:hover { color: #fecaca; }

/* ── Shared dialog widening — used by both the tabbed dialog and the wrongness viewer ── */
._eli3_dialog_wide { width: 620px; max-width: 94vw; }

/* ─── §15  Tabbed dialog (ELI logo click → Help/Contact/Console)
 *   What: tab bar at top of the dialog body + active-tab underline +
 *     individual tab panels (help, contact, console).
 *   Who emits: kernel's _tabbedDialog() + _buildHelpTab / _buildContactTab
 *     / _buildConsoleTab.
 *   Override: rare. Tool authors don't customize this dialog. */
._eli3_tabs {
  display: flex;
  gap: 0;
  border-bottom: 2px solid #e2e8f0;
  margin-bottom: var(--space-3);
}
._eli3_tab {
  padding: var(--space-2) 14px;
  font: var(--weight-bold) var(--font-md)/1.2 var(--font-family);
  letter-spacing: 0.4px;
  text-transform: uppercase;
  color: var(--text-status-footer);
  cursor: pointer;
  border-bottom: 2px solid transparent;
  margin-bottom: -2px;
  transition: color .15s, border-color .15s;
}
._eli3_tab:hover { color: var(--color-blue); }
._eli3_tab_active {
  color: var(--color-blue);
  border-bottom-color: var(--color-blue);
}
._eli3_tabpanel {
  font-size: 12px;
  line-height: 1.5;
  color: var(--text-on-light);
  /* Lock height so dialog doesn't reflow when switching tabs.
     Sized to fit the tallest tab (Console: toolbar + 360px log list). */
  min-height: 420px;
}

/* Help tab */
._eli3_help_section {
  margin-bottom: var(--space-4);
  padding-bottom: var(--space-3);
  border-bottom: 1px solid #f1f5f9;
}
._eli3_help_section:last-child { border-bottom: none; padding-bottom: 0; }
._eli3_help_section h4 {
  font: var(--weight-extrabold) var(--font-md)/1.3 var(--font-family);
  letter-spacing: 0.6px;
  text-transform: uppercase;
  color: var(--color-blue);
  margin: 0 0 var(--space-2);
}
._eli3_help_section p {
  font-size: 12px;
  line-height: 1.55;
  color: var(--text-on-light);
  margin: 0 0 var(--space-2);
}
._eli3_help_section ul {
  margin: var(--space-1) 0 0 var(--space-3);
  padding: 0;
}
._eli3_help_section li {
  margin-bottom: var(--space-1);
  font-size: 12px;
  line-height: 1.55;
  color: var(--text-on-light);
}
._eli3_help_section code {
  font-family: var(--font-mono);
  font-size: var(--font-md);
  background: #f1f5f9;
  border: 1px solid #e2e8f0;
  padding: 1px var(--space-1);
  color: var(--text-on-light);
}

/* Help → Recovery actions block */
#_eli3_help_recovery_btns {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: var(--space-2);
}
#_eli3_help_recovery_btns .btn-action {
  flex: 0 0 auto;
  text-align: center;
}

/* Contact tab — kv table */
._eli3_kv_row {
  display: grid;
  grid-template-columns: 110px 1fr;
  gap: var(--space-3);
  padding: 6px 0;
  border-bottom: 1px solid #f1f5f9;
  font-size: 12px;
}
._eli3_kv_row:last-child { border-bottom: none; }
._eli3_kv_label {
  font-weight: var(--weight-bold);
  color: var(--text-status-footer);
}
._eli3_kv_value {
  flex: 1;
  font-family: var(--font-mono);
  word-break: break-all;
  color: var(--text-on-light);
}

/* Console tab — toolbar + log list */
._eli3_console_toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1);
  align-items: center;
  padding: 6px var(--space-2);
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  margin-bottom: 6px;
}
._eli3_filter_btn {
  padding: 4px 10px;
  font: var(--weight-bold) var(--font-xs)/1 var(--font-family);
  letter-spacing: 0.3px;
  text-transform: uppercase;
  background: linear-gradient(to bottom, #f7f9fa 0%, #dce3e8 100%);
  border: 1px solid #b0bec5;
  color: var(--text-status-footer);
  cursor: pointer;
  transition: all .15s ease;
}
._eli3_filter_btn:hover {
  background: linear-gradient(to bottom, #ffffff 0%, #e3f2fd 100%);
  border-color: #90caf9;
  color: var(--color-blue);
}
._eli3_filter_btn_active {
  background: linear-gradient(135deg, var(--color-blue) 0%, var(--color-blue-deep) 100%);
  color: #fff;
  border-color: var(--color-blue-deep);
}
._eli3_filter_btn_active:hover {
  background: linear-gradient(135deg, #1976d2 0%, var(--color-blue) 100%);
  color: #fff;
  border-color: var(--color-blue);
}
/* Copy + Clear buttons in the console toolbar — same platinum treatment */
._eli3_console_toolbar button:not(._eli3_filter_btn) {
  padding: 4px 10px;
  font: var(--weight-bold) var(--font-xs)/1 var(--font-family);
  letter-spacing: 0.3px;
  text-transform: uppercase;
  background: linear-gradient(to bottom, #f7f9fa 0%, #dce3e8 100%);
  border: 1px solid #b0bec5;
  color: var(--text-status-footer);
  cursor: pointer;
  transition: all .15s ease;
}
._eli3_console_toolbar button:not(._eli3_filter_btn):hover {
  background: linear-gradient(to bottom, #ffffff 0%, #e3f2fd 100%);
  border-color: #90caf9;
  color: var(--color-blue);
}
._eli3_console_meta {
  margin-left: auto;
  font: var(--weight-semibold) var(--font-sm)/1 var(--font-family);
  color: var(--text-dim);
}
._eli3_log_list {
  max-height: 360px;
  overflow-y: auto;
  border: 1px solid #e2e8f0;
}
._eli3_log_row {
  display: flex;
  gap: 6px;
  padding: var(--space-1) var(--space-2);
  border-bottom: 1px solid #f1f5f9;
  font: var(--font-md)/1.4 var(--font-mono);
  flex-wrap: wrap;
}
._eli3_log_time { color: var(--text-dim); flex-shrink: 0; }
._eli3_log_chan {
  color: var(--color-blue);
  font-weight: var(--weight-bold);
  flex-shrink: 0;
  min-width: 50px;
}
._eli3_log_msg { flex: 1; color: var(--text-on-light); }
._eli3_log_payload {
  width: 100%;
  margin-top: 2px;
  padding-left: 56px;
  font-size: var(--font-sm);
  color: var(--text-status-footer);
  word-break: break-all;
}
._eli3_log_empty {
  padding: var(--space-3);
  text-align: center;
  font-style: italic;
  color: var(--text-dim);
  font-size: var(--font-md);
}
